import { ReactNode, FC } from 'react';

interface FormRule {
    /** 是否必填 */
    required?: boolean;
    /** 正则表达式 */
    pattern?: RegExp;
    /** 最小长度 */
    min?: number;
    /** 最大长度 */
    max?: number;
    /** 校验函数 */
    validator?: (value: any) => boolean | Promise<boolean>;
    /** 错误提示 */
    message?: string;
}
interface FormItemProps {
    /** 字段名 */
    name: string;
    /** 标签 */
    label?: ReactNode;
    /** 是否必填 */
    required?: boolean;
    /** 校验规则 */
    rules?: FormRule[];
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface FormProps {
    /** 表单值 */
    values?: Record<string, any>;
    /** 初始值 */
    initialValues?: Record<string, any>;
    /** 布局方式 */
    layout?: 'horizontal' | 'vertical';
    /** 标签宽度 */
    labelWidth?: string | number;
    /** 值变化回调 */
    onValuesChange?: (changedValues: Record<string, any>, allValues: Record<string, any>) => void;
    /** 提交回调 */
    onSubmit?: (values: Record<string, any>) => void;
    /** 校验失败回调 */
    onFinishFailed?: (errors: any[]) => void;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

type FormComponent = FC<FormProps> & {
    Item: FC<FormItemProps>;
};
declare const Form: FormComponent;
declare const FormItem: FC<FormItemProps>;

export { Form, FormItem, Form as default };
export type { FormItemProps, FormProps, FormRule };
